/**
 * ConsoleChat.io v2.0.0 - Underground Developer Meeting Room
 * Requires: <script src="https://cdn.socket.io/4.8.1/socket.io.min.js"></script>
 */
const cc=(function(io,window){'use strict';const SERVER_URL='https://console-chat-server.herokuapp.com';let socket=null;let started=false;const initSocket=()=>{if(!socket){if(typeof io==='undefined'){console.error('ConsoleChat: Socket.IO not loaded.');return false}socket=io(SERVER_URL,{transports:['websocket','polling'],reconnection:true,reconnectionAttempts:5,reconnectionDelay:1000});setupSocketListeners()}return true};const setupSocketListeners=()=>{socket.on('welcome_message',(data)=>{console.log(`${data.message}`)});socket.on('new_message',(data)=>{if(started){if(!data.error){console.log(`@${data.hostname} #${data.channel} ${data.username}: ${data.message}`)}else{console.log(`${data.message}`)}}});socket.on('message_to_user',(data)=>{if(started){console.log(`${data.message}`)}});socket.on('new_user_connected',(data)=>{if(started){console.log(`${data.message}`)}});socket.on('show_channel_list',(data)=>{if(started){if(data.message.length>0){console.log('Available channels:');for(let i=0;i<data.message.length;i++){console.log(`  - ${data.message[i]}`)}}else{console.log('No channels available.')}}});socket.on('show_user_list',(data)=>{if(started){if(data.message.length>0){console.log('Users on this channel:');for(let i=0;i<data.message.length;i++){console.log(`  - ${data.message[i]}`)}}else{console.log('No other users on this channel.')}}});socket.on('connect',()=>{if(started){console.log('ConsoleChat: Connected')}});socket.on('disconnect',(reason)=>{if(started){console.log('ConsoleChat: Disconnected -',reason)}});socket.on('connect_error',(error)=>{if(started){console.log('ConsoleChat: Connection error -',error.message)}})};const start=()=>{if(!initSocket())return;started=true;console.log('ConsoleChat started! Type cc.help() for commands.');socket.emit('start')};const close=()=>{started=false;console.log('ConsoleChat closed');if(socket){socket.disconnect()}};const onsite=()=>{if(!started){console.log('Run cc.start() first');return}socket.emit('onsite')};const publicChannel=()=>{if(!started){console.log('Run cc.start() first');return}socket.emit('public')};const help=()=>{console.log('ConsoleChat Commands:\n──────────────────────────────────────────\ncc.start()                    - Launch chat\ncc.help()                     - Show this help\ncc.username("name")           - Set your nickname\ncc.public()                   - Join global channel\ncc.onsite()                   - Chat only on this website\ncc.say("message")             - Send a message\ncc.msg("user", "message")     - Send private message\ncc.join("channel")            - Join or create channel\ncc.join("channel", "private") - Create private channel\ncc.list()                     - Show available channels\ncc.who()                      - Show users on channel\ncc.leave()                    - Leave current channel\ncc.close()                    - Close chat')};const username=(newUsername)=>{if(!started){console.log('Run cc.start() first');return}if(!newUsername||typeof newUsername!=='string'){console.log('Usage: cc.username("your_name")');return}socket.emit('change_username',{nickName:newUsername})};const say=(msg)=>{if(!started){console.log('Run cc.start() first');return}if(!msg||typeof msg!=='string'){console.log('Usage: cc.say("your message")');return}socket.emit('new_message',{message:msg,hostname:window.location.hostname})};const msg=(nickname,message)=>{if(!started){console.log('Run cc.start() first');return}if(!nickname||!message){console.log('Usage: cc.msg("username", "your message")');return}socket.emit('new_private_message',{message:message,hostname:window.location.hostname,nickname:nickname})};const join=(channel,type)=>{if(!started){console.log('Run cc.start() first');return}if(!channel||typeof channel!=='string'){console.log('Usage: cc.join("channel_name")');return}socket.emit('join',{channel:channel,type:type})};const list=()=>{if(!started){console.log('Run cc.start() first');return}socket.emit('list')};const who=()=>{if(!started){console.log('Run cc.start() first');return}socket.emit('who')};const leave=()=>{if(!started){console.log('Run cc.start() first');return}socket.emit('leave')};return{start:start,close:close,help:help,username:username,say:say,msg:msg,join:join,leave:leave,list:list,who:who,public:publicChannel,onsite:onsite}})(typeof io!=='undefined'?io:null,window);
